7	/**
8	 * Derives an owner's canonical region ('locality'). The postcode is preferred: a
9	 * postcode falling in a known region's range ({@code NSW 2000-2099}, {@code VIC
10	 * 3000-3099}, {@code QLD 4000-4099}) determines the region directly. Only when the
11	 * postcode is absent or in no known range does derivation fall back to the fixed
12	 * city-to-region table. A city (or postcode) that resolves to no region derives the
13	 * locality {@code "UNKNOWN"}.
14	 */
15	public final class Localities {
16	
17	    /** Fixed city -> canonical region table. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	            "Sydney", "NSW",
20	            "Melbourne", "VIC",
21	            "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_RANGE = Map.of(
25	            "NSW", new int[] {2000, 2099},
26	            "VIC", new int[] {3000, 3099},
27	            "QLD", new int[] {4000, 4099});
28	
29	    /** The locality returned when neither postcode nor city resolves to a region. */
30	    public static final String UNKNOWN = "UNKNOWN";
31	
32	    private Localities() {
33	    }
34	
35	    /**
36	     * Derives the owner's locality from its {@code customerCode} identity ({@code '<REGION>-<HASH8>'}),
37	     * whose REGION is the canonical region: the locality is the region encoded in the code. Owners
38	     * with no {@code customerCode} yet (e.g. seed data) fall back to deriving the region directly from
39	     * postcode and city.
40	     *
41	     * @param owner the owner (must not be {@code null}).
42	     * @return the canonical region for the owner, or {@code "UNKNOWN"} when none resolves.
43	     */
44	    public static String localityFor(Owner owner) {
45	        String code = owner.getCustomerCode();
46	        if (code != null) {
47	            int dash = code.indexOf('-');
48	            if (dash > 0) {
49	                return code.substring(0, dash);
50	            }
51	        }
52	        return localityFor(owner.getCity(), owner.getPostcode());
53	    }
54	
55	    /**
56	     * Derives the region from the city alone. Equivalent to {@link #localityFor(String,
57	     * String)} with a {@code null} postcode.
58	     *
59	     * @param city the owner's city (may be {@code null}).
60	     * @return the canonical region for {@code city}, or {@code "UNKNOWN"} when the
61	     *         city is {@code null} or not in the fixed table.
62	     */
63	    public static String localityFor(String city) {
64	        return localityFor(city, null);
65	    }
66	
67	    /**
68	     * Derives the region, preferring the postcode. The postcode is consulted first: if
69	     * it falls in a known region's range, that region is returned. Otherwise (postcode
70	     * absent, malformed, or out of every range) derivation falls back to the
71	     * city-to-region table.
72	     *
73	     * @param city     the owner's city (may be {@code null}).
74	     * @param postcode the owner's postcode (may be {@code null}).
75	     * @return the canonical region, or {@code "UNKNOWN"} when neither resolves.
76	     */
77	    public static String localityFor(String city, String postcode) {
78	        String byPostcode = regionForPostcode(postcode);
79	        if (byPostcode != null) {
80	            return byPostcode;
81	        }
82	        return city == null ? UNKNOWN : CITY_REGION.getOrDefault(city, UNKNOWN);
83	    }
84	
85	    /**
86	     * @return the region whose range contains {@code postcode}, or {@code null} when
87	     *         the postcode is {@code null}, not a 4-digit number, or in no known range.
88	     */
89	    private static String regionForPostcode(String postcode) {
90	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
91	            return null;
92	        }
93	        int value = Integer.parseInt(postcode);
94	        for (Map.Entry<String, int[]> entry : REGION_RANGE.entrySet()) {
95	            int[] range = entry.getValue();
96	            if (value >= range[0] && value <= range[1]) {
97	                return entry.getKey();
98	            }
99	        }
100	        return null;
101	    }
102	}
